#!/usr/bin/env bash
# CFR-5 (openspec change ci-failure-reporting): the CI failure issue body names what failed and
# cannot execute or inject log text.
#
# hack/ci/ci-failure-issue-body.sh builds the body of the issue (or comment) that the CI failure
# reporter writes for a failed scheduled run. This test runs it on the recorded fixtures under
# hack/test/testdata/ci-failure-report/ (generated by read-only gh calls; the generator is in
# openspec/changes/ci-failure-reporting/evidence/T1.1.md) and on hostile logs built here.
#
# What it locks:
#   * the first line is the bot marker (CFR-4 shape) and the body names the workflow and run URL;
#   * exactly the failed (or timed-out) jobs are listed, each with its failed step name, also
#     when the logs are unavailable or have no FAIL line; a run with no failed job lists none;
#   * the first 50 FAIL lines in order, no more; the whole body stays under 60000 bytes (so under
#     GitHub's 65536-character limit), the excerpt fence is closed before a visible truncation
#     marker, truncation never drops a job, and a line cut mid-character stays valid UTF-8;
#   * log text is never evaluated; the excerpt fence is longer than any backtick run inside it;
#     no @mention, HTML comment, entity or extra list item appears outside a fence, through log
#     text or job names, and the only marker is the real one on line 1;
#   * marker inputs that would break the marker line are refused, and a job list too long for the
#     cap is refused rather than cut.
#
# Usage:
#   hack/test/ci_failure_report_test.sh              # check the repository tree
#   hack/test/ci_failure_report_test.sh <tree-root>  # check an arbitrary tree root
set -euo pipefail

FAILURES=0

bad() {
  echo "FAIL: $*" >&2
  FAILURES=$((FAILURES + 1))
}

ok() {
  echo "ok - $*"
}

ROOT="${1:-}"
if [[ -z "${ROOT}" ]]; then
  ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
fi
ROOT="${ROOT%/}"

command -v jq >/dev/null 2>&1 || {
  echo "FAIL: jq not found; install jq to run this test" >&2
  exit 1
}

BUILDER="${ROOT}/hack/ci/ci-failure-issue-body.sh"
FX="${ROOT}/hack/test/testdata/ci-failure-report"
for f in "${BUILDER}" "${FX}/jobs-38871014363.json" "${FX}/jobs-two-failed.json" \
  "${FX}/jobs-timed-out.json" "${FX}/log-failed-excerpt.txt"; do
  [[ -f "${f}" ]] || {
    echo "FAIL: ${f#"${ROOT}"/} is missing" >&2
    exit 1
  }
done

# One scratch root for the whole run, created in THIS shell so the EXIT trap sees it.
WORK="$(mktemp -d)"
trap 'rm -rf "${WORK:?}"' EXIT

RUN_URL='https://github.com/PlatformRelay/Kollect/actions/runs/38871014363'
MARKER='<!-- ci-failure-report v1 workflow=.github/workflows/e2e-nightly.yaml run_id=38871014363 key=162.1 event=failure -->'
TS='2026-08-05T05:56:50.0005226Z'
TAB=$'\t'

# build <case> [args...]: run the builder with the standard marker inputs plus args, with a
# fresh empty directory as its working directory. Sets BODY (stdout file), ERR, RC and CWD.
build() {
  local name="$1"
  shift
  CWD="${WORK}/${name}/cwd"
  BODY="${WORK}/${name}/body.md"
  ERR="${WORK}/${name}/stderr"
  mkdir -p "${CWD}"
  RC=0
  (cd "${CWD}" && bash "${BUILDER}" --workflow-name 'E2E nightly' \
    --workflow-path .github/workflows/e2e-nightly.yaml --run-id 38871014363 \
    --run-url "${RUN_URL}" --key 162.1 "$@") >"${BODY}" 2>"${ERR}" || RC=$?
}

# items <file>: the list items of the "### Failed jobs" section.
items() {
  awk '/^### / { s = ($0 == "### Failed jobs"); next } s && /^- / { print }' "$1"
}

# outside <file>: the lines outside fenced code blocks, by the CommonMark rule for backtick
# fences (opened by 3+ backticks after at most 3 spaces; closed by a line of only backticks, at
# least as many, and spaces). An opener whose info string holds a backtick is not a fence.
# Prints "UNCLOSED-FENCE" when the file ends inside a fence.
outside() {
  awk '
    !inf {
      if (match($0, /^ ? ? ?```+[^`]*$/)) { s = $0; sub(/^ */, "", s); match(s, /^`+/); flen = RLENGTH; inf = 1; next }
      print; next
    }
    {
      s = $0
      if (s ~ /^ ? ? ?`+ *$/) { gsub(/ /, "", s); if (length(s) >= flen) inf = 0 }
    }
    END { if (inf) print "UNCLOSED-FENCE" }
  ' "$1"
}

# fences <file>: "<line number> <backtick count>" for each opening and closing fence line.
fences() {
  awk '
    !inf && match($0, /^ ? ? ?```+[^`]*$/) { s = $0; sub(/^ */, "", s); match(s, /^`+/); flen = RLENGTH; inf = 1; print NR, flen; next }
    inf { s = $0; if (s ~ /^ ? ? ?`+ *$/) { gsub(/ /, "", s); if (length(s) >= flen) { inf = 0; print NR, length(s) } } }
  ' "$1"
}

# --- 0. oracle control: the fence model itself ----------------------------------------------
# A backtick in the opener's info string makes it a paragraph, not a fence (CommonMark); a
# shorter backtick line does not close a longer fence; a proper fence hides its content.
oracle="${WORK}/oracle.md"
printf '%s\n' '```x`y' 'bad @one' '````' 'hidden @two' '```' 'still hidden @three' '````' 'shown @four' >"${oracle}"
got="$(outside "${oracle}" | tr '\n' '|')"
fl="$(fences "${oracle}" | tr '\n' '|')"
if [[ "${got}" == '```x`y|bad @one|shown @four|' && "${fl}" == '3 4|7 4|' ]]; then
  ok "oracle: an info string with a backtick opens no fence; a short backtick line does not close a long one"
else
  bad "oracle: the fence model is wrong; outside gave '${got}', fences gave '${fl}'"
fi

# --- 1. two failed jobs: exactly those two are listed ----------------------------------------
build two-failed --jobs "${FX}/jobs-two-failed.json" --log "${FX}/log-failed-excerpt.txt"
got="$(items "${BODY}")"
n="$(grep -c '' <<<"${got}" || true)"
[[ -n "${got}" ]] || n=0
if [[ "${RC}" -eq 0 && "${n}" -eq 2 ]] && grep -q 'e2e-multitenant' <<<"${got}" &&
  grep -q 'e2e-finalizer-cleanup' <<<"${got}" &&
  ! grep -qE 'e2e-smoke|e2e-bench|extract-budget|scale-envtest-10k|race' <<<"${got}"; then
  ok "two failed jobs: the body lists exactly e2e-multitenant and e2e-finalizer-cleanup"
else
  bad "two failed jobs: expected exactly 2 items naming e2e-multitenant and e2e-finalizer-cleanup under '### Failed jobs' (exit ${RC}), got ${n}: ${got:-<none>}"
fi

# --- 2. marker first, workflow and run URL named ---------------------------------------------
first="$(head -n 1 "${BODY}")"
if [[ "${first}" == "${MARKER}" ]] && grep -qF 'E2E nightly' "${BODY}" && grep -qF "${RUN_URL}" "${BODY}"; then
  ok "marker: first line is the CFR-4 marker; workflow name and run URL present"
else
  bad "marker: expected first line '${MARKER}' and the body to name 'E2E nightly' and ${RUN_URL}; first line: '${first}'"
fi

# --- 3. FAIL lines are bounded at 50 ---------------------------------------------------------
log="${WORK}/eighty.log"
for i in $(seq 1 80); do
  printf 'e2e-multitenant%sUNKNOWN STEP%s%s noise line %s\n' "${TAB}" "${TAB}" "${TS}" "${i}"
  printf 'e2e-multitenant%sUNKNOWN STEP%s%s --- FAIL: TestBound%s (0.01s)\n' "${TAB}" "${TAB}" "${TS}" "${i}"
done >"${log}"
build eighty --jobs "${FX}/jobs-two-failed.json" --log "${log}"
got="$(grep -o -- '--- FAIL: TestBound[0-9]* ' "${BODY}" | grep -o '[0-9][0-9]*' | tr '\n' ' ' || true)"
want="$(seq 1 50 | tr '\n' ' ')"
if [[ "${RC}" -eq 0 && "${got}" == "${want}" ]]; then
  ok "FAIL bound: 80 FAIL lines in the log, the first 50 in the body, in order"
else
  bad "FAIL bound: expected TestBound1..50 in order, once each (exit ${RC}), got: ${got:-<none>}"
fi

# --- 4. a log over the cap: body under 60000, fence closed before the marker, jobs kept ------
log="${WORK}/huge.log"
pad="$(printf 'x%.0s' $(seq 1 5000))"
for i in $(seq 1 60); do
  printf 'e2e-finalizer-cleanup%sUNKNOWN STEP%s%s FAIL huge%s %s\n' "${TAB}" "${TAB}" "${TS}" "${i}" "${pad}"
done >"${log}"
build huge --jobs "${FX}/jobs-two-failed.json" --log "${log}"
size="$(wc -c <"${BODY}")"
size="${size//[[:space:]]/}"
trunc_line="$(grep -n 'truncated' "${BODY}" | tail -n 1 | cut -d: -f1 || true)"
last_close="$(fences "${BODY}" | awk 'NR % 2 == 0 { l = $1 } END { print l + 0 }')"
got="$(items "${BODY}")"
if [[ "${RC}" -eq 0 && "${size}" -gt 0 && "${size}" -lt 60000 && -n "${trunc_line}" ]] &&
  [[ "${last_close}" -gt 0 && "${trunc_line}" -gt "${last_close}" ]] &&
  ! outside "${BODY}" | grep -qx 'UNCLOSED-FENCE' &&
  outside "${BODY}" | grep -q 'truncated' &&
  grep -q 'e2e-multitenant' <<<"${got}" && grep -q 'e2e-finalizer-cleanup' <<<"${got}" &&
  grep -qF 'FAIL huge1 ' "${BODY}"; then
  ok "cap: ${size} bytes < 60000, excerpt fence closed (line ${last_close}) before the truncation marker (line ${trunc_line}), both jobs listed"
else
  bad "cap: expected a body of 1..59999 bytes with a closed fence, a 'truncated' marker after it outside the fence, the first FAIL line, and both failed jobs; got ${size} bytes, marker line '${trunc_line}', last fence close '${last_close}', exit ${RC}"
fi

# --- 5. timed-out job with no FAIL line: listed with its failed step name --------------------
log="${WORK}/timeout.log"
printf 'e2e-smoke%sUNKNOWN STEP%s%s waiting for pods\n' "${TAB}" "${TAB}" "${TS}" >"${log}"
build timeout --jobs "${FX}/jobs-timed-out.json" --log "${log}"
got="$(items "${BODY}")"
if [[ "${RC}" -eq 0 ]] && grep -q 'e2e-smoke' <<<"${got}" &&
  grep 'e2e-smoke' <<<"${got}" | grep -qF 'Run ./.github/actions/kind-e2e-setup'; then
  ok "timed out: e2e-smoke listed with failed step 'Run ./.github/actions/kind-e2e-setup'"
else
  bad "timed out: expected an item naming e2e-smoke and its failed step 'Run ./.github/actions/kind-e2e-setup' (exit ${RC}), got: ${got:-<none>}"
fi

# --- 6. hostile log text appears verbatim and never runs -------------------------------------
# shellcheck disable=SC2016 # the command substitution and backticks are the payload, unexpanded
l1='FAIL $(touch pwned) dollar-paren'
# shellcheck disable=SC2016
l2='FAIL `touch pwned` backticks'
log="${WORK}/hostile.log"
printf 'e2e-multitenant%sUNKNOWN STEP%s%s %s\ne2e-multitenant%sUNKNOWN STEP%s%s %s\n' \
  "${TAB}" "${TAB}" "${TS}" "${l1}" "${TAB}" "${TAB}" "${TS}" "${l2}" >"${log}"
build hostile --jobs "${FX}/jobs-two-failed.json" --log "${log}"
if [[ "${RC}" -eq 0 ]] && grep -qF -- "${l1}" "${BODY}" && grep -qF -- "${l2}" "${BODY}" &&
  [[ ! -e "${CWD}/pwned" && ! -e "${WORK}/pwned" && ! -e "${ROOT}/pwned" ]]; then
  ok "hostile text: \$(...) and backtick lines appear verbatim, no pwned file"
else
  bad "hostile text: expected both lines verbatim and no pwned file (exit ${RC}); pwned in cwd: $([[ -e "${CWD}/pwned" ]] && echo yes || echo no)"
fi

# --- 7. Markdown injection: long backtick run, @user, marker lookalike -----------------------
fake='<!-- ci-failure-report v1 workflow=.github/workflows/e2e-nightly.yaml run_id=1 key=999.9 event=recovery -->'
inj="FAIL \`\`\`\`\` ping @user ${fake}"
log="${WORK}/inject.log"
printf 'e2e-multitenant%sUNKNOWN STEP%s%s %s\n' "${TAB}" "${TAB}" "${TS}" "${inj}" >"${log}"
build inject --jobs "${FX}/jobs-two-failed.json" --log "${log}"
inj_line="$(grep -nF -- "${inj}" "${BODY}" | head -n 1 | cut -d: -f1 || true)"
open_len="$(fences "${BODY}" | awk -v l="${inj_line:-0}" 'NR % 2 == 1 && $1 < l { o = $2 } END { print o + 0 }')"
close_after="$(fences "${BODY}" | awk -v l="${inj_line:-0}" 'NR % 2 == 0 && $1 > l { print $1; exit }')"
outside "${BODY}" >"${WORK}/inject.outside"
markers="$(grep -c 'ci-failure-report' "${WORK}/inject.outside" || true)"
if [[ "${RC}" -eq 0 && -n "${inj_line}" && "${open_len}" -gt 5 && -n "${close_after}" ]] &&
  ! grep -qx 'UNCLOSED-FENCE' "${WORK}/inject.outside" &&
  ! grep -qF -- "${inj}" "${WORK}/inject.outside" &&
  ! grep -q '@user' "${WORK}/inject.outside" &&
  [[ "$(head -n 1 "${BODY}")" == "${MARKER}" && "${markers}" -eq 1 ]]; then
  ok "injection: fence of ${open_len} backticks closes at line ${close_after} after the line; no @user or marker lookalike outside it"
else
  bad "injection: expected the line inside a fence longer than 5 backticks that closes after it, no @user outside a fence, and the real marker as the only marker outside fences (exit ${RC}); line '${inj_line}', fence ${open_len}, close '${close_after}', markers outside ${markers}"
fi

# --- 8. @ in a job name is neutralised -------------------------------------------------------
jobs="${WORK}/jobs-at.json"
jq '.jobs |= map(if .name == "e2e-multitenant" then .name = "deploy @user" else . end)' \
  "${FX}/jobs-two-failed.json" >"${jobs}"
build at-name --jobs "${jobs}" --log "${FX}/log-failed-excerpt.txt"
got="$(items "${BODY}")"
if [[ "${RC}" -eq 0 ]] && grep -q 'deploy' <<<"${got}" && grep 'deploy' <<<"${got}" | grep -q 'user' &&
  ! outside "${BODY}" | grep -q '@user'; then
  ok "job name: 'deploy @user' listed with the @ neutralised, no @user outside a fence"
else
  bad "job name: expected an item naming 'deploy' and 'user' and no '@user' outside a fence (exit ${RC}), got: ${got:-<none>}"
fi

# --- 8b. a job name cannot add a list item, an HTML comment or an entity ---------------------
jobs="${WORK}/jobs-hostile-names.json"
jq --arg n1 $'evil\n- injected item <!-- ci-failure-report v1 workflow=.github/workflows/e2e-nightly.yaml run_id=1 key=999.9 event=recovery -->' \
  --arg n2 'amp &#64;user' \
  '.jobs |= map(if .name == "e2e-multitenant" then .name = $n1 elif .name == "e2e-finalizer-cleanup" then .name = $n2 else . end)' \
  "${FX}/jobs-two-failed.json" >"${jobs}"
build hostile-names --jobs "${jobs}" --log "${FX}/log-failed-excerpt.txt"
got="$(items "${BODY}")"
n="$(grep -c '' <<<"${got}" || true)"
[[ -n "${got}" ]] || n=0
outside "${BODY}" | tail -n +2 >"${WORK}/hostile-names.outside"
if [[ "${RC}" -eq 0 && "${n}" -eq 2 && "$(head -n 1 "${BODY}")" == "${MARKER}" ]] &&
  grep -q 'evil.*injected item' <<<"${got}" && grep -q 'amp.*user' <<<"${got}" &&
  ! grep -qF '<!--' "${WORK}/hostile-names.outside" && ! grep -qF '&#64;' "${WORK}/hostile-names.outside"; then
  ok "job names: a newline, '<!--' marker lookalike and '&#64;' stay text in one item each"
else
  bad "job names: expected 2 items, the real marker on line 1, and no '<!--' or '&#64;' outside a fence after line 1 (exit ${RC}), got ${n}: ${got:-<none>}"
fi

# --- 9. logs unavailable: jobs still listed --------------------------------------------------
: >"${WORK}/empty.log"
mkdir -p "${WORK}/logdir"
for variant in no-log empty-log unreadable-log; do
  if [[ "${variant}" == no-log ]]; then
    build "${variant}" --jobs "${FX}/jobs-two-failed.json"
  elif [[ "${variant}" == empty-log ]]; then
    build "${variant}" --jobs "${FX}/jobs-two-failed.json" --log "${WORK}/empty.log"
  else
    build "${variant}" --jobs "${FX}/jobs-two-failed.json" --log "${WORK}/logdir"
  fi
  got="$(items "${BODY}")"
  if [[ "${RC}" -eq 0 ]] && grep -qF 'logs unavailable' "${BODY}" &&
    grep -q 'e2e-multitenant' <<<"${got}" && grep -q 'e2e-finalizer-cleanup' <<<"${got}"; then
    ok "logs unavailable (${variant}): both failed jobs listed and 'logs unavailable' said"
  else
    bad "logs unavailable (${variant}): expected both failed jobs listed and the text 'logs unavailable' (exit ${RC})"
  fi
done

# --- 10. no failed job: says so, lists none --------------------------------------------------
build none --jobs "${FX}/jobs-38871014363.json" --log "${FX}/log-failed-excerpt.txt"
got="$(items "${BODY}")"
if [[ "${RC}" -eq 0 && -z "${got}" ]] && grep -qi 'no failed job' "${BODY}"; then
  ok "no failed job: the body says so and lists none"
else
  bad "no failed job: expected 'no failed job' and no items under '### Failed jobs' (exit ${RC}), got: ${got:-<none>}"
fi

# --- 11. marker inputs that would break the marker line are refused --------------------------
for arg in "--key 162.1-->" "--run-id 1x" "--workflow-path .github/workflows/a b.yaml" \
  "--run-url https://example.com/x"; do
  flag="${arg%% *}"
  build refuse --jobs "${FX}/jobs-two-failed.json" "${flag}" "${arg#* }"
  if [[ "${RC}" -ne 0 && ! -s "${BODY}" ]]; then
    ok "refused: ${arg} (exit ${RC}, no body)"
  else
    bad "refused: expected a non-zero exit and no body for ${arg}, got exit ${RC} and $(wc -c <"${BODY}") bytes"
  fi
done

# --- 12. a line cut mid-character stays valid UTF-8 ------------------------------------------
command -v iconv >/dev/null 2>&1 || {
  echo "FAIL: iconv not found; it checks the UTF-8 case" >&2
  exit 1
}
e_acute="$(printf '\xc3\xa9')"
prefix="e2e-multitenant${TAB}UNKNOWN STEP${TAB}${TS} FAIL utf8 "
plen="${#prefix}" # ASCII only, so characters = bytes
# The builder cuts at 4000 bytes: make byte 4000 fall inside a two-byte character.
if [[ $(((4000 - plen) % 2)) -eq 0 ]]; then
  prefix+="x"
fi
log="${WORK}/utf8.log"
{
  printf '%s' "${prefix}"
  for _ in $(seq 1 3000); do printf '%s' "${e_acute}"; done
  printf '\n'
} >"${log}"
build utf8 --jobs "${FX}/jobs-two-failed.json" --log "${log}"
if [[ "${RC}" -eq 0 ]] && grep -qF 'FAIL utf8 ' "${BODY}" && iconv -f UTF-8 -t UTF-8 "${BODY}" >/dev/null 2>&1; then
  ok "UTF-8: a 6000-byte line cut at 4000 bytes, mid-character, leaves a valid UTF-8 body"
else
  bad "UTF-8: expected the cut line in the body and the body to be valid UTF-8 (exit ${RC})"
fi

# --- 13. a job list too long for the cap is refused, never cut -------------------------------
jobs="${WORK}/jobs-oversized.json"
jq '.jobs[0] as $j | .jobs = [range(0; 300) | $j | .name = ("@" * 200) | .conclusion = "failure"]' \
  "${FX}/jobs-two-failed.json" >"${jobs}"
build oversized --jobs "${jobs}" --log "${FX}/log-failed-excerpt.txt"
if [[ "${RC}" -ne 0 && ! -s "${BODY}" ]] && grep -q 'does not fit' "${ERR}"; then
  ok "oversized job list: refused (exit ${RC}), no body"
else
  bad "oversized job list: expected a non-zero exit, no body and 'does not fit' on stderr, got exit ${RC} and $(wc -c <"${BODY}") bytes"
fi

if [[ "${FAILURES}" -gt 0 ]]; then
  echo "ci_failure_report_test: ${FAILURES} check(s) failed" >&2
  exit 1
fi
echo "All ci-failure-report body checks passed."
